/**
 * Unit tests: S20 nec_1099_aggregate RPC contract shapes and threshold logic.
 *
 * No real DB required — all Supabase calls are mocked via vi.fn().
 * These tests cover:
 *   1. The $600 threshold (60000 cents) boundary: ≥60000 = met, <60000 = not met.
 *   2. nec_threshold_met boolean logic from the contract types.
 *   3. Empty artists array shape returned when RPC has no rows.
 *   4. threshold_met_count matches only artists where nec_threshold_met=true.
 *   5. total_artists counts all artists regardless of threshold status.
 *
 * Coverage: pure unit — no I/O. All tests run unconditionally.
 */

import { describe, it, expect, vi } from 'vitest'
import { RPC, cents } from '@/lib/payments/contracts'
import type {
  Nec1099AggregateResult,
  Nec1099AggregateArtistRow,
} from '@/lib/payments/contracts'

// ---------------------------------------------------------------------------
// Inline mock — a minimal supabase-shaped object with a mockable .rpc()
// ---------------------------------------------------------------------------

function makeRpcMock(
  handler: (fn: string, args: Record<string, unknown>) => Promise<{ data: unknown; error: null | { message: string } }>,
) {
  const rpcFn = vi.fn((fn: string, args: Record<string, unknown>) => handler(fn, args))
  return {
    rpc: { bind: vi.fn(() => rpcFn) },
    _rpcFn: rpcFn,
  }
}

// ---------------------------------------------------------------------------
// Helpers: build typed artist rows for assertions
// ---------------------------------------------------------------------------

function makeArtistRow(overrides: Partial<Nec1099AggregateArtistRow>): Nec1099AggregateArtistRow {
  return {
    artist_id: 'artist-' + Math.random().toString(36).slice(2, 8),
    artist_name: 'Test Artist',
    total_paid_cents: cents(0),
    nec_threshold_met: false,
    stripe_1099_capable: false,
    ...overrides,
  }
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe('nec_1099_aggregate contract', () => {

  // Test 1: Pure math — $600 = 60000 cents is the IRS 1099-NEC threshold.
  it('threshold is 60000 cents ($600) for nec_threshold_met=true', () => {
    const NEC_THRESHOLD_CENTS = 60000

    // Exactly at threshold — met
    expect(cents(60000) >= NEC_THRESHOLD_CENTS).toBe(true)

    // One cent below — not met
    expect(cents(59999) >= NEC_THRESHOLD_CENTS).toBe(false)

    // Above threshold — met
    expect(cents(100000) >= NEC_THRESHOLD_CENTS).toBe(true)

    // Zero — not met
    expect(cents(0) >= NEC_THRESHOLD_CENTS).toBe(false)
  })

  // Test 2: nec_threshold_met boolean logic used when parsing RPC result rows.
  it('nec_threshold_met is false when total_paid_cents < 60000', () => {
    const NEC_THRESHOLD_CENTS = 60000

    const cases: Array<{ paid: number; expected: boolean }> = [
      { paid: 0, expected: false },
      { paid: 1, expected: false },
      { paid: 59999, expected: false },
      { paid: 60000, expected: true },
      { paid: 60001, expected: true },
      { paid: 999999, expected: true },
    ]

    for (const { paid, expected } of cases) {
      const row = makeArtistRow({
        total_paid_cents: cents(paid),
        nec_threshold_met: cents(paid) >= NEC_THRESHOLD_CENTS,
      })
      expect(row.nec_threshold_met).toBe(expected)
    }
  })

  // Test 3: Empty artists array — RPC returns the correct zero-state structure.
  it('returns empty artists array structure when no results', async () => {
    const emptyResult: Nec1099AggregateResult = {
      year: 2026,
      studio_id: '11111111-1111-4111-8111-111111111111',
      artists: [],
      total_artists: 0,
      threshold_met_count: 0,
    }

    const { _rpcFn } = makeRpcMock(async (fn) => {
      expect(fn).toBe(RPC.NEC_1099_AGGREGATE)
      return { data: emptyResult, error: null }
    })

    const rpc = _rpcFn
    const { data, error } = await rpc(RPC.NEC_1099_AGGREGATE, {
      p_studio_id: '11111111-1111-4111-8111-111111111111',
      p_year: 2026,
    })

    expect(error).toBeNull()

    const result = data as Nec1099AggregateResult
    expect(result.total_artists).toBe(0)
    expect(result.threshold_met_count).toBe(0)
    expect(result.artists).toHaveLength(0)
    expect(result.year).toBe(2026)
    expect(result.studio_id).toBe('11111111-1111-4111-8111-111111111111')
  })

  // Test 4: threshold_met_count matches only artists where nec_threshold_met=true.
  it('threshold_met_count matches artists where nec_threshold_met is true', async () => {
    const artists: Nec1099AggregateArtistRow[] = [
      makeArtistRow({ artist_id: 'a1', total_paid_cents: cents(120000), nec_threshold_met: true }),
      makeArtistRow({ artist_id: 'a2', total_paid_cents: cents(60000), nec_threshold_met: true }),
      makeArtistRow({ artist_id: 'a3', total_paid_cents: cents(30000), nec_threshold_met: false }),
    ]

    const mockResult: Nec1099AggregateResult = {
      year: 2026,
      studio_id: 'studio-abc',
      artists,
      total_artists: 3,
      threshold_met_count: 2,
    }

    const { _rpcFn } = makeRpcMock(async () => ({ data: mockResult, error: null }))

    const { data } = await _rpcFn(RPC.NEC_1099_AGGREGATE, {
      p_studio_id: 'studio-abc',
      p_year: 2026,
    })

    const result = data as Nec1099AggregateResult

    // threshold_met_count must equal the number of artists with nec_threshold_met=true
    const metCount = result.artists.filter(a => a.nec_threshold_met).length
    expect(result.threshold_met_count).toBe(metCount)
    expect(result.threshold_met_count).toBe(2)
  })

  // Test 5: total_artists includes ALL artists regardless of threshold status.
  it('total_artists includes all artists regardless of threshold', async () => {
    const artists: Nec1099AggregateArtistRow[] = [
      makeArtistRow({ artist_id: 'a1', total_paid_cents: cents(80000), nec_threshold_met: true }),
      makeArtistRow({ artist_id: 'a2', total_paid_cents: cents(10000), nec_threshold_met: false }),
      makeArtistRow({ artist_id: 'a3', total_paid_cents: cents(0), nec_threshold_met: false }),
    ]

    const mockResult: Nec1099AggregateResult = {
      year: 2026,
      studio_id: 'studio-xyz',
      artists,
      total_artists: 3,
      threshold_met_count: 1,
    }

    const { _rpcFn } = makeRpcMock(async () => ({ data: mockResult, error: null }))

    const { data } = await _rpcFn(RPC.NEC_1099_AGGREGATE, {
      p_studio_id: 'studio-xyz',
      p_year: 2026,
    })

    const result = data as Nec1099AggregateResult

    // total_artists must equal artists.length — all rows, not just threshold-met
    expect(result.total_artists).toBe(result.artists.length)
    expect(result.total_artists).toBe(3)

    // Verify threshold_met_count is strictly less than total_artists (only 1 of 3 met)
    expect(result.threshold_met_count).toBeLessThan(result.total_artists)
    expect(result.threshold_met_count).toBe(1)
  })
})

/**
 * Unit tests: S19/S20 invoice webhook cases in process-stripe-event.ts
 *
 * Covers the handleInvoiceStatusUpdate shared helper via:
 *   • invoice.payment_failed  → STRIPE_INVOICE_UPDATE_STATUS_FROM_WEBHOOK with status='open'
 *   • invoice.voided          → STRIPE_INVOICE_UPDATE_STATUS_FROM_WEBHOOK with status='void'
 *   • RPC failure             → handleInvoiceStatusUpdate re-throws (BullMQ retry path)
 *
 * Supabase mocked via vi.fn(). No real DB required. All tests run unconditionally.
 *
 * IMPLEMENTATION STATUS:
 *   All 3 tests — active; invoice handlers landed in process-stripe-event.ts (S19).
 *
 * Coverage (3 tests):
 *   1. invoice.payment_failed → STRIPE_INVOICE_UPDATE_STATUS_FROM_WEBHOOK called with p_status='open'
 *   2. invoice.voided         → STRIPE_INVOICE_UPDATE_STATUS_FROM_WEBHOOK called with p_status='void'
 *   3. RPC error              → processStripeEvent throws (BullMQ retry)
 */

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { RPC } from '@/lib/payments/contracts'
import type { StripeEventLike, SupabaseServiceClient } from '@/lib/payments/process-stripe-event'

// ---------------------------------------------------------------------------
// Mock logger — must be hoisted before any import of the module under test
// ---------------------------------------------------------------------------

vi.mock('@/lib/logger', () => ({
  logger: { info: vi.fn(), warn: vi.fn(), error: vi.fn(), debug: vi.fn() },
}))

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

type RpcHandler = (
  fn: string,
  args: Record<string, unknown>,
) => Promise<{ data: unknown; error: null | { message: string } }>

// ---------------------------------------------------------------------------
// Supabase mock factory — mirrors the pattern from process-stripe-event-saga.test.ts
//
// The production handleInvoiceStatusUpdate uses:
//   supabase.rpc.bind(supabase) as unknown as UntypedRpc
// So the mock's rpc must have a .bind() that returns a callable vi.fn().
//
// Note: invoice handlers do NOT call supabase.from(), so we only need a minimal
// from stub to satisfy the SupabaseServiceClient interface.
// ---------------------------------------------------------------------------

function makeSupabaseMock(rpcHandler?: RpcHandler): {
  sb: SupabaseServiceClient
  rpcFn: ReturnType<typeof vi.fn>
} {
  const defaultHandler: RpcHandler = async () => ({ data: { id: 'mock-result' }, error: null })
  const handler = rpcHandler ?? defaultHandler

  const rpcFn = vi.fn(async (fn: string, args: Record<string, unknown>) => handler(fn, args))

  const fromFn = vi.fn(() => ({
    select: vi.fn(() => ({
      eq: vi.fn(() => ({
        maybeSingle: vi.fn(async () => ({ data: { studio_id: 'studio-test-001' }, error: null })),
        single: vi.fn(async () => ({ data: null, error: null })),
      })),
    })),
    update: vi.fn(() => ({
      eq: vi.fn(async () => ({ error: null })),
    })),
  }))
  Object.assign(fromFn, { bind: vi.fn(() => fromFn) })

  const sb = {
    rpc: { bind: vi.fn(() => rpcFn) },
    from: fromFn,
  } as unknown as SupabaseServiceClient

  return { sb, rpcFn }
}

// ---------------------------------------------------------------------------
// Event factory — builds a minimal Stripe invoice event
// ---------------------------------------------------------------------------

function makeInvoiceEvent(
  type: 'invoice.payment_failed' | 'invoice.voided' | 'invoice.finalized' | 'invoice.payment_succeeded',
  overrides: Partial<{
    id: string
    status: string | null
    total: number
    subtotal: number
    tax: number | null
    amount_paid: number
    amount_due: number
    payment_intent: string | null
    currency: string
    automatic_tax: { status: string | null } | null
    metadata: Record<string, string>
    status_transitions: Record<string, number | null>
  }> = {},
): StripeEventLike {
  return {
    id: `evt_inv_${Math.random().toString(36).slice(2, 10)}`,
    type,
    data: {
      object: {
        id: 'in_test_001',
        status: 'open',
        total: 10000,
        subtotal: 10000,
        tax: null,
        amount_paid: 0,
        amount_due: 10000,
        payment_intent: 'pi_test_001',
        currency: 'usd',
        automatic_tax: null,
        metadata: {},
        status_transitions: {},
        ...overrides,
      },
    },
  }
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe('processStripeEvent — S19/S20 invoice webhook paths', () => {
  let processStripeEvent: (
    event: StripeEventLike,
    supabase: SupabaseServiceClient,
  ) => Promise<void>

  beforeEach(async () => {
    vi.clearAllMocks()
    const mod = await import('@/lib/payments/process-stripe-event')
    processStripeEvent = mod.processStripeEvent
  })

  // Test 1: invoice.payment_failed → status update with p_status='open'
  it('invoice.payment_failed: calls STRIPE_INVOICE_UPDATE_STATUS_FROM_WEBHOOK with status=open', async () => {
    const rpcCalls: Array<{ fn: string; args: Record<string, unknown> }> = []

    const { sb } = makeSupabaseMock(async (fn, args) => {
      rpcCalls.push({ fn, args })
      return { data: { id: 'inv_1', status: 'open' }, error: null }
    })

    const event = makeInvoiceEvent('invoice.payment_failed', {
      id: 'in_failed_001',
      status: 'open',
      amount_paid: 0,
      payment_intent: 'pi_failed_001',
    })

    await processStripeEvent(event, sb)

    const invoiceUpdateCall = rpcCalls.find(
      c => c.fn === RPC.STRIPE_INVOICE_UPDATE_STATUS_FROM_WEBHOOK,
    )
    expect(invoiceUpdateCall).toBeDefined()
    expect(invoiceUpdateCall?.args.p_status).toBe('open')
    expect(invoiceUpdateCall?.args.p_invoice_id).toBe('in_failed_001')
  })

  // Test 2: invoice.voided → status update with p_status='void'
  it('invoice.voided: calls STRIPE_INVOICE_UPDATE_STATUS_FROM_WEBHOOK with status=void', async () => {
    const rpcCalls: Array<{ fn: string; args: Record<string, unknown> }> = []

    const { sb } = makeSupabaseMock(async (fn, args) => {
      rpcCalls.push({ fn, args })
      return { data: { id: 'inv_2', status: 'void' }, error: null }
    })

    const event = makeInvoiceEvent('invoice.voided', {
      id: 'in_voided_001',
      status: 'void',
      amount_paid: 0,
      payment_intent: null,
    })

    await processStripeEvent(event, sb)

    const invoiceUpdateCall = rpcCalls.find(
      c => c.fn === RPC.STRIPE_INVOICE_UPDATE_STATUS_FROM_WEBHOOK,
    )
    expect(invoiceUpdateCall).toBeDefined()
    expect(invoiceUpdateCall?.args.p_status).toBe('void')
    expect(invoiceUpdateCall?.args.p_invoice_id).toBe('in_voided_001')
  })

  // Test 3: RPC returns error → handleInvoiceStatusUpdate re-throws → BullMQ retries
  it('handleInvoiceStatusUpdate: re-throws when STRIPE_INVOICE_UPDATE_STATUS_FROM_WEBHOOK RPC returns error', async () => {
    const { sb } = makeSupabaseMock(async (fn) => {
      if (fn === RPC.STRIPE_INVOICE_UPDATE_STATUS_FROM_WEBHOOK) {
        return { data: null, error: { message: 'DB error: invoice row not found' } }
      }
      return { data: { id: 'mock' }, error: null }
    })

    const event = makeInvoiceEvent('invoice.payment_failed', {
      id: 'in_error_001',
      status: 'open',
      payment_intent: 'pi_error_001',
    })

    // processStripeEvent must throw so the webhook BullMQ job is retried
    await expect(processStripeEvent(event, sb)).rejects.toThrow()
  })
})

