/**
 * Unit tests: S19/S20 invoice/PI branch routing in createSessionPaymentIntent.
 *
 * The function routes to createSessionInvoice when studioHasActiveTaxRegistrations()
 * returns true; otherwise it calls stripe.paymentIntents.create directly.
 *
 * studioHasActiveTaxRegistrations is defined in the SAME file as createSessionPaymentIntent
 * (lib/stripe/charges.ts) so we cannot mock it in isolation. Instead we control its return
 * value by injecting a supabase mock that returns different data for the
 * 'stripe_tax_registrations' table query it runs internally.
 *
 * requireStudioL2Enabled (capability-gate) and ensureCountryAligned also hit supabase
 * before the tax-reg check. The stateful mock handles all three.
 *
 * vi.mock() calls are hoisted and must not reference variables declared in module scope
 * (Vitest limitation) — inline stubs only.
 *
 * Coverage (4 tests):
 *   1. Invoice path taken when studioHasActiveTaxRegistrations returns true.
 *   2. PI path taken when no tax registrations exist.
 *   3. Deposit rollback called when createSessionInvoice throws (with depositDrawdownCents > 0).
 *   4. stripe_charge_record RPC called with invoice paymentIntentId on invoice success.
 */

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { RPC, cents } from '@/lib/payments/contracts'
import type { CreateSessionPaymentIntentArgs } from '@/lib/stripe/charges'

// ---------------------------------------------------------------------------
// Hoist mocks — no outer-scope variable references allowed in vi.mock factories
// ---------------------------------------------------------------------------

vi.mock('@/lib/logger', () => ({
  logger: { info: vi.fn(), warn: vi.fn(), error: vi.fn(), debug: vi.fn() },
}))

vi.mock('@/lib/stripe/invoices', () => ({
  createSessionInvoice: vi.fn(),
}))

vi.mock('@/lib/stripe/idempotency', () => ({
  idempotencyKeyFor: vi.fn(
    (scope: string, ctx: Record<string, unknown>) =>
      `idem-${scope}-${JSON.stringify(ctx)}` as string,
  ),
  withIdempotencyKey: vi.fn(
    async <T>(key: string, fn: (k: string) => Promise<T>) => fn(key),
  ),
}))

vi.mock('@/lib/stripe/client', () => ({
  getStripe: vi.fn(),
}))

vi.mock('@/lib/payments/capability-gate', () => ({
  // eslint-disable-next-line @typescript-eslint/no-extraneous-class
  CapabilityGateError: class CapabilityGateError extends Error {
    public reason: string
    public userMessage: string
    public httpStatus: number
    constructor(reason: string, userMessage: string, httpStatus = 403) {
      super(`capability_gate: ${reason}`)
      this.name = 'CapabilityGateError'
      this.reason = reason
      this.userMessage = userMessage
      this.httpStatus = httpStatus
    }
  },
  requireStudioL2Enabled: vi.fn(),
}))

// ---------------------------------------------------------------------------
// Typed imports — after mock declarations
// ---------------------------------------------------------------------------

import { createSessionInvoice } from '@/lib/stripe/invoices'
import { getStripe } from '@/lib/stripe/client'
import { requireStudioL2Enabled } from '@/lib/payments/capability-gate'

// ---------------------------------------------------------------------------
// Supabase mock factory
//
// Handles the 3 query patterns that fire before the PI/invoice branch:
//   1. requireStudioL2Enabled  → supabase.rpc(STUDIO_L2_PAYMENTS_ENABLED)  — mocked via capability-gate mock above
//   2. ensureCountryAligned    → supabase.from('studios').select('country').eq().single()
//                                supabase.from('stripe_connected_accounts').select('country').eq().eq().single()
//   3. APPLY_DEPOSIT_TO_SESSION → supabase.rpc(APPLY_DEPOSIT_TO_SESSION)   — only when depositDrawdownCents > 0
//   4. studioHasActiveTaxRegs  → supabase.from('stripe_tax_registrations').select('id').eq().eq().limit()
//   5. createSessionInvoice    → mocked module (does not use this supabase)
//   6. STRIPE_CHARGE_RECORD    → supabase.rpc(STRIPE_CHARGE_RECORD)
//   7. ROLLBACK_DEPOSIT        → supabase.rpc(ROLLBACK_DEPOSIT_APPLICATION)  — on error path
// ---------------------------------------------------------------------------

interface SupabaseMockOptions {
  /** Return data for stripe_tax_registrations.limit() query. Controls invoice/PI branch. */
  taxRegistrations: Array<{ id: string }>
  /** Return data for STRIPE_CHARGE_RECORD rpc. */
  chargeRecordResult?: { id: string }
  /** Return data for APPLY_DEPOSIT_TO_SESSION rpc. */
  applyDepositResult?: { transaction_id: string }
  /** If true, ROLLBACK_DEPOSIT_APPLICATION returns error. */
  rollbackDepositError?: boolean
}

function makeSupabaseMock(opts: SupabaseMockOptions) {
  const rpcCalls: Array<{ fn: string; args: Record<string, unknown> }> = []

  const rpcFn = vi.fn(async (fn: string, args: Record<string, unknown>) => {
    rpcCalls.push({ fn, args })

    if (fn === RPC.APPLY_DEPOSIT_TO_SESSION) {
      return {
        data: opts.applyDepositResult ?? { transaction_id: 'txn-deposit-test-001' },
        error: null,
      }
    }

    if (fn === RPC.STRIPE_CHARGE_RECORD) {
      return { data: opts.chargeRecordResult ?? { id: 'charge-row-001' }, error: null }
    }

    if (fn === RPC.ROLLBACK_DEPOSIT_APPLICATION) {
      if (opts.rollbackDepositError) {
        return { data: null, error: { message: 'rollback failed' } }
      }
      return { data: { id: 'rollback-ok' }, error: null }
    }

    // Default — return success for any other RPC (e.g. STUDIO_L2_PAYMENTS_ENABLED fallback
    // in case the mock module isn't called first — defensive)
    return { data: { id: 'mock-default' }, error: null }
  })

  // from() stateful mock: routes by table name
  const fromFn = vi.fn((table: string) => {
    if (table === 'studios') {
      // ensureCountryAligned studios.country query
      return {
        select: vi.fn(() => ({
          eq: vi.fn(() => ({
            single: vi.fn(async () => ({ data: { country: 'US' }, error: null })),
          })),
        })),
      }
    }

    if (table === 'stripe_connected_accounts') {
      // ensureCountryAligned + studioHasActiveTaxRegs (this one uses .eq().eq().limit())
      return {
        select: vi.fn(() => ({
          eq: vi.fn(() => ({
            single: vi.fn(async () => ({ data: { country: 'US' }, error: null })),
            eq: vi.fn(() => ({
              single: vi.fn(async () => ({ data: { country: 'US' }, error: null })),
              limit: vi.fn(async () => ({ data: [{ id: 'acct-studio-001' }], error: null })),
            })),
          })),
        })),
      }
    }

    if (table === 'stripe_tax_registrations') {
      // studioHasActiveTaxRegistrations: .select('id').eq('studio_id', x).eq('status', 'active').limit(1)
      return {
        select: vi.fn(() => ({
          eq: vi.fn(() => ({
            eq: vi.fn(() => ({
              limit: vi.fn(async () => ({
                data: opts.taxRegistrations,
                error: null,
              })),
            })),
          })),
        })),
      }
    }

    // Default fallback for any other table
    return {
      select: vi.fn(() => ({
        eq: vi.fn(() => ({
          single: vi.fn(async () => ({ data: null, error: null })),
          maybeSingle: vi.fn(async () => ({ data: null, error: null })),
          limit: vi.fn(async () => ({ data: [], error: null })),
        })),
      })),
    }
  })

  // attach .bind() so the bind-cast pattern resolves correctly
  Object.assign(fromFn, { bind: vi.fn(() => fromFn) })

  const sb = {
    rpc: rpcFn,
    from: fromFn,
  }

  return { sb, rpcCalls, fromFn, rpcFn }
}

