describe('createSessionPaymentIntent — S19/S20 invoice/PI branch routing', () => {
  let createSessionPaymentIntent: (
    supabase: ReturnType<typeof makeSupabaseMock>['sb'],
    args: CreateSessionPaymentIntentArgs,
  ) => Promise<unknown>

  beforeEach(async () => {
    vi.clearAllMocks()

    // requireStudioL2Enabled is fully mocked — always passes silently
    vi.mocked(requireStudioL2Enabled).mockResolvedValue({ accountId: 'acct_studio_001' })

    // Default: createSessionInvoice returns a valid result
    vi.mocked(createSessionInvoice).mockResolvedValue({
      invoiceId: 'in_test_001',
      paymentIntentId: 'pi_test_001',
      paymentIntentClientSecret: null,
      paymentIntentStatus: 'succeeded',
      taxAmountCents: cents(100),
      totalCents: cents(5100),
    })

    // Default: getStripe returns a mock stripe instance with a working paymentIntents.create
    vi.mocked(getStripe).mockReturnValue({
      paymentIntents: {
        create: vi.fn().mockResolvedValue({
          id: 'pi_direct_001',
          client_secret: 'pi_direct_001_secret',
          status: 'succeeded',
          amount: 5000,
          currency: 'usd',
        }),
      },
    } as unknown as ReturnType<typeof import('@/lib/stripe/client').getStripe>)

    const mod = await import('@/lib/stripe/charges')
    createSessionPaymentIntent = mod.createSessionPaymentIntent as typeof createSessionPaymentIntent
  })

  // Test 1: Invoice path — studioHasActiveTaxRegistrations returns true → createSessionInvoice called
  it('calls createSessionInvoice when studioHasActiveTaxRegistrations returns true', async () => {
    const { sb } = makeSupabaseMock({
      taxRegistrations: [{ id: 'taxreg_001' }], // non-empty → invoice branch
    })

    const result = await createSessionPaymentIntent(sb, makeArgs())

    expect(vi.mocked(createSessionInvoice)).toHaveBeenCalledTimes(1)
    expect(result).toMatchObject({ paymentIntentId: 'pi_test_001' })
  })

  // Test 2: PI path — no tax registrations → stripe.paymentIntents.create called instead
  it('calls stripe.paymentIntents.create when no tax registrations', async () => {
    const { sb } = makeSupabaseMock({
      taxRegistrations: [], // empty → PI branch
    })

    const stripeInstance = vi.mocked(getStripe)()
    const piCreateSpy = vi.mocked(stripeInstance.paymentIntents.create)

    await createSessionPaymentIntent(sb, makeArgs())

    expect(vi.mocked(createSessionInvoice)).not.toHaveBeenCalled()
    expect(piCreateSpy).toHaveBeenCalledTimes(1)
  })

  // Test 3: createSessionInvoice throws + depositDrawdownCents > 0 → rollback_deposit_application called
  it('rolls back deposit when createSessionInvoice throws (depositDrawdownCents > 0)', async () => {
    vi.mocked(createSessionInvoice).mockRejectedValueOnce(new Error('stripe invoice error'))

    const { sb, rpcCalls } = makeSupabaseMock({
      taxRegistrations: [{ id: 'taxreg_001' }],
    })

    const args = makeArgs({
      depositDrawdownCents: cents(1000), // > 0 → deposit was reserved before invoice call
    })

    await expect(createSessionPaymentIntent(sb, args)).rejects.toThrow('stripe invoice error')

    const rollbackCall = rpcCalls.find(c => c.fn === RPC.ROLLBACK_DEPOSIT_APPLICATION)
    expect(rollbackCall).toBeDefined()
    expect(rollbackCall?.args.p_reason).toBe('payment_failed')
  })

  // Test 4: Invoice path success → stripe_charge_record called with invoice paymentIntentId
  it('records stripe_charges from invoice paymentIntentId when invoice path succeeds', async () => {
    vi.mocked(createSessionInvoice).mockResolvedValue({
      invoiceId: 'in_success_001',
      paymentIntentId: 'pi_invoice_success_001',
      paymentIntentClientSecret: null,
      paymentIntentStatus: 'succeeded',
      taxAmountCents: cents(200),
      totalCents: cents(5200),
    })

    const { sb, rpcCalls } = makeSupabaseMock({
      taxRegistrations: [{ id: 'taxreg_001' }],
    })

    await createSessionPaymentIntent(sb, makeArgs())

    const chargeRecordCall = rpcCalls.find(c => c.fn === RPC.STRIPE_CHARGE_RECORD)
    expect(chargeRecordCall).toBeDefined()
    expect(chargeRecordCall?.args.p_payment_intent_id).toBe('pi_invoice_success_001')
    expect(chargeRecordCall?.args.p_tax_amount_cents).toBe(200)
  })
})
